// Simple K-means clustering over review scores (used as a demo seed).
// Replace with a real clustering library or pre-computed cluster ids from Qdrant.
const k = 3;
const points = $json.result || $json;

// Normalize input to an array of { text, score }.
const items = Array.isArray(points)
  ? points.map((p) => ({
      text: p.payload?.review || p.payload?.text || '',
      score: Number(p.payload?.rating || p.payload?.score || 0)
    }))
  : [null].filter(Boolean);

// Mini k-means on the 1-D 'score' feature.
const values = items.map((i) => i.score);
if (!values.length) return { json: { clusters: [] } };

let centroids = [];
for (let c = 0; c < k; c++) {
  centroids.push(values[Math.floor((c * values.length) / k)] || 0);
}
let assignments = new Array(items.length).fill(0);

for (let iter = 0; iter < 20; iter++) {
  let changed = false;
  for (let i = 0; i < items.length; i++) {
    let best = 0;
    let bestDist = Infinity;
    for (let c = 0; c < k; c++) {
      const d = Math.abs(values[i] - centroids[c]);
      if (d < bestDist) { bestDist = d; best = c; }
    }
    if (assignments[i] !== best) { assignments[i] = best; changed = true; }
  }
  // Recompute centroids.
  for (let c = 0; c < k; c++) {
    const members = values.filter((_, i) => assignments[i] === c);
    centroids[c] = members.length ? members.reduce((a, b) => a + b, 0) / members.length : centroids[c];
  }
  if (!changed) break;
}

const clusters = k === 0 ? [] : Array.from({ length: k }, (_, c) => ({
  cluster: c,
  centroid: centroids[c],
  items: items.filter((_, i) => assignments[i] === c)
}));

return { json: { clusters } };

// Flatten clusters into a list with a cluster label per item.
const rows = [];
for (const c of ($json.clusters || [])) {
  for (const item of c.items || []) {
    rows.push({
      cluster: `Cluster ${c.cluster}`,
      centroid: c.centroid,
      text: item.text,
      score: item.score
    });
  }
}
return rows.map((r) => ({ json: r }));
